// GENERATED by scripts/sync-shared.mjs from src/ - do not edit here; run `npm run sync:shared`.
/**
 * Partial updates: a file whose name says which stage it holds replaces only that stage in the
 * live dataset, so organisers upload one small file per round instead of everything every time.
 *
 *   group / group-stage   → teams and group-stage results
 *   qf / quarter          → quarter-final rows
 *   sf / semi             → semi-final rows
 *   final                 → the Final, plus any other knockout rounds the file contains
 *                           (so the organisers' full "(Finals)" export updates the whole bracket)
 *
 * Files without a keyword are a full replacement (handled by the caller).
 */
import type { KnockoutMatch, KnockoutRound, TournamentData, WorkbookFile } from '../types/tournament.ts';
import { advanceWinners, parseKnockoutFiles, parseWorkbookFiles } from './excelParser.ts';
import { describeParseError, type ImportIssue } from './importValidation.ts';

export type UploadScope = 'group' | KnockoutRound;

export const SCOPE_LABELS: Record<UploadScope, string> = {
  group: 'Group stage (teams and group results)',
  QF: 'Quarter finals',
  SF: 'Semi finals',
  F: 'Final',
};

const ROUND_ORDER: KnockoutRound[] = ['QF', 'SF', 'F'];

/** Stage named in the file name, or null when the name has no stage keyword. */
export function scopeFromFileName(fileName: string): UploadScope | null {
  const name = fileName.toLowerCase().replace(/\.[^.]+$/, '');
  if (/group/.test(name)) return 'group';
  if (/semi|(^|[^a-z])sf([^a-z]|$)/.test(name)) return 'SF';
  if (/quarter|(^|[^a-z])qf([^a-z]|$)/.test(name)) return 'QF';
  if (/final/.test(name)) return 'F';
  return null;
}

export interface MergeResult {
  data: TournamentData | null;
  errors: ImportIssue[];
  /** Rounds / stages actually replaced, in display order. */
  updated: UploadScope[];
}

/**
 * Applies partial-update files on top of the live dataset. Returns the merged data, or errors
 * when something cannot be applied (nothing is published in that case).
 */
export function mergeIntoDataset(current: TournamentData | null, files: { file: WorkbookFile; scope: UploadScope }[]): MergeResult {
  const errors: ImportIssue[] = [];
  const updated = new Set<UploadScope>();
  const groupFiles = files.filter((f) => f.scope === 'group').map((f) => f.file);
  const knockoutFiles = files.filter((f): f is { file: WorkbookFile; scope: KnockoutRound } => f.scope !== 'group');

  let base: TournamentData | null = current ? structuredClone(current) : null;

  if (groupFiles.length > 0) {
    try {
      const parsed = parseWorkbookFiles(groupFiles);
      base = {
        ...parsed,
        // Keep the live bracket unless this upload also carries knockout files.
        knockout: base?.knockout ?? parsed.knockout,
        meta: { ...parsed.meta, knockoutSheet: base?.meta.knockoutSheet ?? parsed.meta.knockoutSheet },
      };
      updated.add('group');
    } catch (e) {
      errors.push({ message: `${groupFiles.map((f) => f.fileName).join(', ')}: ${describeParseError(e)}` });
    }
  }

  if (!base) {
    errors.push({
      message:
        'Nothing has been published yet, so a knockout-only file cannot be applied. Upload the group results first (file name containing "group").',
    });
    return { data: null, errors, updated: [] };
  }

  for (const { file, scope } of knockoutFiles) {
    let parsed: ReturnType<typeof parseKnockoutFiles>;
    try {
      parsed = parseKnockoutFiles([file], base.teams);
    } catch (e) {
      errors.push({ message: `${file.fileName}: ${describeParseError(e)}` });
      continue;
    }
    if (!parsed.sheetName) {
      errors.push({ message: `${file.fileName}: no finals table was found (expected Match, Racks A, Racks B and team columns).` });
      continue;
    }
    // "final" files update every round they contain; qf/sf files update only their own round.
    const rounds: KnockoutRound[] =
      scope === 'F' ? ROUND_ORDER.filter((r) => parsed.knockout.some((k) => k.round === r)) : [scope];
    if (rounds.length === 0) {
      errors.push({ message: `${file.fileName}: contains no ${SCOPE_LABELS[scope].toLowerCase()} rows.` });
      continue;
    }
    const replacement = parsed.knockout.filter((k) => rounds.includes(k.round));
    if (scope !== 'F' && replacement.length === 0) {
      errors.push({ message: `${file.fileName}: contains no ${SCOPE_LABELS[scope].toLowerCase()} rows.` });
      continue;
    }
    base.knockout = [...base.knockout.filter((k) => !rounds.includes(k.round)), ...replacement];
    base.meta.knockoutSheet = parsed.sheetName;
    rounds.forEach((r) => updated.add(r));
  }

  base.knockout = advanceWinners(renumber(base.knockout));
  base.meta.fileName = files.map((f) => f.file.fileName).join(' + ');
  const order: UploadScope[] = ['group', ...ROUND_ORDER];
  return { data: errors.length > 0 ? null : base, errors, updated: order.filter((s) => updated.has(s)) };
}

function renumber(matches: KnockoutMatch[]): KnockoutMatch[] {
  return [...matches]
    .sort((a, b) => ROUND_ORDER.indexOf(a.round) - ROUND_ORDER.indexOf(b.round) || a.id.localeCompare(b.id, undefined, { numeric: true }))
    .map((m, i) => ({ ...m, order: i }));
}
